import Foundation

/// Which sound a tap makes. Each has a fixed meaning (mirrors `web/src/ui/clickSounds.ts`):
///  - `.nav` — the bottom tab bar
///  - one per tab — buttons on that tab's screens (sheets opened from a tab use the same sound)
///  - `.onboarding` — first-run setup
/// Files live in Resources/Audio/Clicks (generated by Scripts/make_click_sounds.py).
enum ButtonSound: String, CaseIterable, Sendable {
    case nav
    case today
    case mealPlan
    case log
    case foods
    case workout
    case progress
    case coach
    case onboarding

    init(tab: MainTab) {
        switch tab {
        case .today: self = .today
        case .mealPlan: self = .mealPlan
        case .log: self = .log
        case .foods: self = .foods
        case .workout: self = .workout
        case .progress: self = .progress
        case .coach: self = .coach
        }
    }

    var fileName: String { rawValue }
}
